package com.bank.extremes;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Finds largest and smallest transaction in one pass for National Bank of India.
public class ExtremesService {
    private static final Logger log = Logger.getLogger(ExtremesService.class.getName());

    // Single pass O(n): seed both trackers with the first element.
    public Extremes findExtremes(BigDecimal[] amounts) {
        if (amounts == null || amounts.length == 0) {
            log.warning("No transactions to analyse today");
            throw new IllegalArgumentException("amounts must be non-empty");
        }
        BigDecimal max = amounts[0];   // seed with a REAL element, not zero
        BigDecimal min = amounts[0];
        for (int i = 1; i < amounts.length; i++) {
            if (amounts[i].compareTo(max) > 0) max = amounts[i]; // bigger → update max
            if (amounts[i].compareTo(min) < 0) min = amounts[i]; // smaller → update min
        }
        final BigDecimal fMax = max, fMin = min;
        log.info(() -> "Largest=Rs." + fMax + " Smallest=Rs." + fMin);
        return new Extremes(max, min);
    }
}
