package com.bank.extremes;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: find the day's biggest and smallest transaction.
public class ExtremesDemo {
    private static final Logger log = Logger.getLogger(ExtremesDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        ExtremesService service = new ExtremesService();

        // Rajesh (SAV2001) day's transactions; negatives are debits.
        BigDecimal[] amounts = {
            new BigDecimal("5000"), new BigDecimal("-1200"),
            new BigDecimal("89000"), new BigDecimal("50"),
            new BigDecimal("-30000")
        };
        Extremes result = service.findExtremes(amounts);
        log.info(() -> "Fraud review: biggest Rs." + result.getMax()
                + ", smallest Rs." + result.getMin());
    }
}
